import java.util.StringTokenizer
import kotlin.math.min
import kotlin.math.max

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()

    val width = min(n, m)
    val height = max(n, m)
    val size = 1 shl width
    val full = size - 1
    val inf = 1_000_000

    val horizontal = IntArray(size)
    val bits = IntArray(size)
    for (mask in 0 until size) {
        horizontal[mask] = mask or ((mask shl 1) and full) or (mask shr 1)
        bits[mask] = Integer.bitCount(mask)
    }

    var dp = IntArray(size * size) { inf }
    for (first in 0 until size) {
        dp[first] = bits[first]
    }

    for (row in 1 until height) {
        val next = IntArray(size * size) { inf }

        for (previousPrevious in 0 until size) {
            for (previous in 0 until size) {
                val value = dp[previousPrevious * size + previous]
                if (value == inf) continue

                val alreadyDominated = horizontal[previous] or previousPrevious
                val required = full xor (alreadyDominated and full)

                for (current in 0 until size) {
                    if ((current and required) != required) continue

                    val index = previous * size + current
                    val candidate = value + bits[current]
                    if (candidate < next[index]) {
                        next[index] = candidate
                    }
                }
            }
        }

        dp = next
    }

    var minimumOccupied = inf
    for (previousPrevious in 0 until size) {
        for (last in 0 until size) {
            val value = dp[previousPrevious * size + last]
            if (value == inf) continue

            if ((horizontal[last] or previousPrevious) == full) {
                minimumOccupied = min(minimumOccupied, value)
            }
        }
    }

    println(n * m - minimumOccupied)
