import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import kotlin.math.min
import kotlin.math.max

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(reader.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()

    val width = min(n, m)
    val height = max(n, m)
    val maskCount = 1 shl width
    val fullMask = maskCount - 1
    val inf = 1_000_000

    val horizontal = IntArray(maskCount)
    val bitCount = IntArray(maskCount)

    for (mask in 0 until maskCount) {
        horizontal[mask] = (mask or (mask shl 1) or (mask shr 1)) and fullMask
        bitCount[mask] = Integer.bitCount(mask)
    }

    var dp = IntArray(maskCount * maskCount) { inf }
    for (current in 0 until maskCount) {
        dp[current] = bitCount[current] // State: previous mask = 0, current mask
    }

    for (row in 1 until height) {
        val next = IntArray(maskCount * maskCount) { inf }

        for (previous in 0 until maskCount) {
            for (current in 0 until maskCount) {
                val value = dp[previous * maskCount + current]
                if (value == inf) continue

                val missing = fullMask and (horizontal[current] or previous).inv()
                var remaining = fullMask xor missing

                var subset = remaining
                while (true) {
                    val nextMask = missing or subset
                    val index = current * maskCount + nextMask
                    val newValue = value + bitCount[nextMask]
                    if (newValue < next[index]) next[index] = newValue

                    if (subset == 0) break
                    subset = (subset - 1) and remaining
                }
            }
        }

        dp = next
    }

    var minimumOccupied = inf
    for (previous in 0 until maskCount) {
        for (current in 0 until maskCount) {
            if ((horizontal[current] or previous) == fullMask) {
                minimumOccupied = min(
                    minimumOccupied,
                    dp[previous * maskCount + current]
                )
            }
        }
    }

    println(n * m - minimumOccupied)
}

import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var result = 0
        while (c > 32) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return result
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val m = fs.nextInt()

    val width = minOf(n, m)
    val height = maxOf(n, m)
    val maskCount = 1 shl width
    val fullMask = maskCount - 1
    val inf = 1_000_000_000

    val horizontalCover = IntArray(maskCount)
    val bitCount = IntArray(maskCount)

    for (mask in 0 until maskCount) {
        horizontalCover[mask] =
            (mask or (mask shl 1) or (mask shr 1)) and fullMask
        bitCount[mask] = Integer.bitCount(mask)
    }

    var dp = IntArray(maskCount * maskCount) { inf }

    for (firstRow in 0 until maskCount) {
        dp[firstRow] = bitCount[firstRow]
    }

    for (row in 1 until height) {
        val next = IntArray(maskCount * maskCount) { inf }

        for (upper in 0 until maskCount) {
            for (current in 0 until maskCount) {
                val value = dp[upper * maskCount + current]
                if (value == inf) continue

                val alreadyCovered = horizontalCover[current] or upper
                val required = fullMask and alreadyCovered.inv()

                for (below in 0 until maskCount) {
                    if ((below and required) != required) continue

                    val index = current * maskCount + below
                    val candidate = value + bitCount[below]
                    if (candidate < next[index]) {
                        next[index] = candidate
                    }
                }
            }
        }

        dp = next
    }

    var minimumOccupied = inf

    for (upper in 0 until maskCount) {
        for (last in 0 until maskCount) {
            val value = dp[upper * maskCount + last]
            if (value == inf) continue
            if ((horizontalCover[last] or upper) == fullMask) {
                minimumOccupied = minOf(minimumOccupied, value)
            }
        }
    }

    println(n * m - minimumOccupied)
}

