fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val m = fs.nextInt()

    val width = minOf(n, m)
    val height = maxOf(n, m)
    val maskCount = 1 shl width
    val fullMask = maskCount - 1
    val stateCount = maskCount * maskCount
    val inf = 1_000_000

    val expanded = IntArray(maskCount)
    val bits = IntArray(maskCount)
    for (mask in 0 until maskCount) {
        expanded[mask] = (mask or (mask shl 1) or (mask shr 1)) and fullMask
        bits[mask] = Integer.bitCount(mask)
    }

    var dp = IntArray(stateCount) { inf }
    dp[fullMask] = 0

    repeat(height) {
        val next = IntArray(stateCount) { inf }

        for (previousSelected in 0 until maskCount) {
            val base = previousSelected * maskCount
            for (previousDominated in 0 until maskCount) {
                val currentCost = dp[base + previousDominated]
                if (currentCost == inf) continue

                for (currentSelected in 0 until maskCount) {
                    if ((previousDominated or currentSelected) != fullMask) continue

                    val currentDominated =
                        expanded[currentSelected] or previousSelected
                    val index = currentSelected * maskCount + currentDominated
                    val newCost = currentCost + bits[currentSelected]

                    if (newCost < next[index]) {
                        next[index] = newCost
                    }
                }
            }
        }

        dp = next
    }

    var minimumOccupied = inf
    for (selected in 0 until maskCount) {
        minimumOccupied = minOf(
            minimumOccupied,
            dp[selected * maskCount + fullMask]
        )
    }

    print(n * m - minimumOccupied)
}
